import{_ as l,o as i,c as e,ai as r}from"./chunks/framework.ampVZV4B.js";const _=JSON.parse('{"title":"按任务选 AI 工具","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/tool-selection.md","filePath":"ai/productivity/tool-selection.md"}'),t={name:"ai/productivity/tool-selection.md"};function o(n,a,s,h,d,c){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="按任务选-ai-工具" tabindex="-1">按任务选 AI 工具 <a class="header-anchor" href="#按任务选-ai-工具" aria-label="Permalink to “按任务选 AI 工具”">​</a></h1><h2 id="场景与问题" tabindex="-1">场景与问题 <a class="header-anchor" href="#场景与问题" aria-label="Permalink to “场景与问题”">​</a></h2><p>“哪个 AI 最好？”是被问得最多、也最没意义的问题。写代码、写周报、查一个技术方案、生成一张封面图，这些任务对模型能力、上下文长度、联网搜索、图像生成的要求完全不同。用通用聊天模型硬啃代码重构，或者用代码专用工具去写公众号文章，都是别扭的：不是做不了，是事倍功半，还容易在错误的地方翻车。</p><p>更实际的问题是成本。工具开一堆订阅，每个月几百块，真正常用的可能有两个。选工具不该看评测榜单，该看自己的任务分布。榜单上的“综合第一”是给所有人看的平均值，而你的任务不是平均分布的。</p><h2 id="做法" tabindex="-1">做法 <a class="header-anchor" href="#做法" aria-label="Permalink to “做法”">​</a></h2><h3 id="_1-按任务类型对号入座" tabindex="-1">1. 按任务类型对号入座 <a class="header-anchor" href="#_1-按任务类型对号入座" aria-label="Permalink to “1. 按任务类型对号入座”">​</a></h3><ul><li><strong>写代码</strong>：优先用带代码库索引的 IDE 类工具（Cursor、Claude Code 等）。关键是能读到你的项目上下文、能直接改文件、能跑命令。纯聊天模型给的代码片段看起来漂亮，放进真实项目往往缺依赖、缺上下文，接缝要自己磨。</li><li><strong>写文档</strong>：通用对话模型（ChatGPT、Claude 网页版）更合适。长文结构、语气调整、多版本改写，这类模型的表达能力和交互便利性更好。写完的终稿自己过一遍，事实必须自己核。</li><li><strong>查资料</strong>：需要联网搜索的场景，用带搜索能力的工具（Perplexity、各大模型的联网模式）。注意区分“搜到的”和“模型编的”，要求它给来源链接，重要结论点开原文核一遍。</li><li><strong>生图</strong>：用专门的图像生成工具（Midjourney、SD、DALL·E 等）。文字模型的生图能力普遍是附赠水平，产出看运气，别指望它稳定出活。</li><li><strong>翻译与润色</strong>：通用对话模型即可，但语气和术语表要给样例，否则译文会一股“翻译腔”。</li><li><strong>数据处理</strong>：结构化数据的清洗统计，让 AI 写代码（Python/pandas）比让它直接算靠谱——它直接算容易在细节上出错，写代码你可以跑验证。</li></ul><h3 id="_2-用组合-不要单选站队" tabindex="-1">2. 用组合，不要单选站队 <a class="header-anchor" href="#_2-用组合-不要单选站队" aria-label="Permalink to “2. 用组合，不要单选站队”">​</a></h3><p>实际工作里任务是串起来的：查资料 → 定方案 → 写代码 → 写文档。对应地用一条链：联网搜索的模型查方案，代码工具实现，通用模型把过程整理成文档。</p><p>单个工具全能不现实，组合起来全能。我的日常组合是三条：</p><ul><li>IDE 里的编码工具：管所有代码相关的事，包括读代码、改代码、写测试。</li><li>一个通用对话模型：管文档、周报、翻译、日常杂问，网页和手机端随时开。</li><li>联网搜索：临时开模型的联网模式或专用搜索工具，用完即走。</li></ul><p>工具数量控制在三个以内。每多一个工具，就多一份订阅费、多一套习惯成本、多一个“这事该用哪个”的决策开销。</p><h3 id="_3-成本与效果的权衡方法" tabindex="-1">3. 成本与效果的权衡方法 <a class="header-anchor" href="#_3-成本与效果的权衡方法" aria-label="Permalink to “3. 成本与效果的权衡方法”">​</a></h3><ul><li><strong>先统计任务分布</strong>：记录一周，写代码多少小时、写文档多少小时、查资料多少次。工具优先级跟着时间占比走，写代码占一半就先为编码工具付费。</li><li><strong>免费额度先试两周</strong>：同一类任务拿手头的真实问题对比两个工具，看产出直接可用的比例，别看演示视频。演示视频挑的是模型最擅长的场景，你的日常不是。</li><li><strong>看“可用率”而不是“惊艳率”</strong>：偶尔一次惊艳的产出不值钱，80% 的情况下拿来就能用才值钱。稳定比上限重要。</li><li><strong>付费退订要干脆</strong>：连续一个月没打开的订阅就是纯亏，砍掉。年付优惠看着划算，但工具迭代极快，锁一年的风险不低，先月付验证习惯再考虑年付。</li><li><strong>留意用量限制</strong>：重度任务撞上限速，在关键时刻掉链子，比贵一点更伤。</li></ul><h3 id="_4-一个试用期对比模板" tabindex="-1">4. 一个试用期对比模板 <a class="header-anchor" href="#_4-一个试用期对比模板" aria-label="Permalink to “4. 一个试用期对比模板”">​</a></h3><p>换新工具时别凭第一印象，用同一组真实任务打分：</p><ul><li>任务样本：从你本周的实际工作里挑 5 个有代表性的问题。</li><li>打分维度：直接可用率（不用改就能用）、修改后可用率、响应速度、成本。</li><li>结论：两周后把两次记录并排看，留下总分高的，另一家退订。</li></ul><p>同一组样本、同一个标准，比较才有意义。样本要覆盖你最常做的那类任务，而不是挑工具擅长的演示题。</p><h3 id="_5-混合场景下的分工示例" tabindex="-1">5. 混合场景下的分工示例 <a class="header-anchor" href="#_5-混合场景下的分工示例" aria-label="Permalink to “5. 混合场景下的分工示例”">​</a></h3><p>拿“给项目写一篇 README”这种混合任务拆一下，就能看出组合的价值：</p><ul><li>结构：让通用对话模型按“简介 / 快速开始 / 配置 / 常见问题”给骨架。</li><li>技术细节：把真实代码库丢给编码工具，让它根据实际的入口、配置项填充命令和参数——这部分通用模型只能编。</li><li>措辞润色：回到通用模型调整语气和段落。</li><li>终审：你自己对着仓库跑一遍命令，确认每条指令真的能执行。</li></ul><p>每个环节用对工具，整体才可能一次成型；只用一个工具硬扛，出来的 README 必然一半靠谱一半是编的。</p><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>没有“最好的 AI”，只有“最适合这类任务的 AI”。</li><li>写代码用带项目上下文的编码工具，写文档用通用对话模型，查资料用带搜索的，生图用专门的生图工具。</li><li>任务是链条，工具也用组合，别指望一个订阅解决所有问题；工具总数控制在三个以内。</li><li>按自己的时间分布决定给谁付费，免费期用真实任务对比可用率。</li><li>稳定可用比偶尔惊艳重要，年付前先用月付验证习惯。</li><li>定期砍掉不用的订阅，工具少而精好过一堆半闲置。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>选 AI 工具的本质是任务匹配：先把自己的任务分类，再让每类任务落到合适的工具上，中间用组合把链路串起来。成本控制的核心不是省钱，是把钱花在时间占比最高的任务上。工具会不断更新换代，但“按任务选、按效果付、按使用率砍”这三条判断标准可以一直用下去。</p>',26)])])}const u=l(t,[["render",o]]);export{_ as __pageData,u as default};
